// 25_ A.3 — owner AUTHORSHIP and external CONTENT are two trust cases and must
// not share one class.
//
// What changed at R3, and why it matters: authority no longer derives from any
// field this workflow can set. Rev 4 let an `origin: 'owner'` flag do it, which
// meant a provider could author content and have it recorded as the owner's.
// Authority now derives ONLY from an `idea_ref` the owner minted at
// /owner/idea, against content the wrapper stored server-side. Anything this
// workflow sends as `owner_content` is a convenience copy: it must canonicalize
// to the stored digest or the request is refused, and it NEVER replaces the
// stored content.
//
// Every external item carries its OWN envelope. An item never inherits
// authority from the enclosing idea — quoting something does not authorise it.
return items.map(i => {
  const ideaRef = i.json.idea_ref || null;          // owner-minted, or absent
  const externals = (i.json.external_items || []).map(it => ({
    envelope: { partition: 'business', trust: 'external-untrusted' },
    source: it.source || 'unknown',
    content: it.content
  }));
  const out = { external_items: externals };
  if (ideaRef) {
    // Case A. The ref is the authority; the copy is only corroborating.
    out.idea_ref = ideaRef;
    if (i.json.owner_content) out.owner_content = i.json.owner_content;
  } else {
    // Case B. No owner authority at all; the top-level envelope is required.
    out.envelope = { partition: 'business', trust: 'external-untrusted' };
  }
  return { json: out };
});

// The A.3 proof obligation, asserted rather than assumed. A future edit that
// let an external item carry instruction authority fails here.
//
// The check reads `authority_components`, not a single top-level authority
// value: 25_ A.3 calls one flattened value for the whole request a defect,
// because it cannot distinguish owner-authored content from the external
// material quoted beside it.
for (const i of items) {
  const comps = i.json.authority_components;
  if (!Array.isArray(comps) || comps.length === 0) {
    throw new Error('A.3 violated: no per-component authority was recorded');
  }
  for (const c of comps) {
    if (String(c.component).startsWith('external_items')
        && c.instruction_authority !== 'none') {
      throw new Error('A.3 violated: an external item acquired authority '
                      + c.instruction_authority);
    }
  }
  if (i.json.external_action_taken_by_this_service !== false) {
    throw new Error('POC-2 takes no external action');
  }
}
return items;
